// Paste into orchestrator Code node: "Build Snapshot Context"
// Runs after Confirm Period — Wait. Creates snapshot_id, writes snapshot_run_context.json.

const fs = require('fs');
const path = require('path');

const cfg = $input.first().json;

function required(name) {
  if (
    cfg[name] === undefined ||
    cfg[name] === null ||
    String(cfg[name]).trim() === '' ||
    String(cfg[name]).startsWith('PUT_') ||
    String(cfg[name]).startsWith('PASTE_')
  ) {
    throw new Error(`Missing required core config: ${name}`);
  }
  return cfg[name];
}

function parseIds(v) {
  if (Array.isArray(v)) return v.map(Number).filter(Number.isFinite);
  return String(v).split(',').map(x => Number(String(x).trim())).filter(Number.isFinite);
}

const now = new Date().toISOString();
const dateStart = String(required('date_start')).trim();
const dateEnd = String(required('date_end')).trim();
const fyEndYear = dateEnd.slice(0, 4);

const snapshotId = cfg.snapshot_id && String(cfg.snapshot_id).trim()
  ? String(cfg.snapshot_id).trim()
  : `eofy_${fyEndYear}_brisbane_${now.replace(/[:.]/g, '-')}`;

const targetCompanyId = Number(required('target_company_id'));
const companyContextIds = parseIds(required('company_context_ids'));
if (!companyContextIds.includes(targetCompanyId)) companyContextIds.unshift(targetCompanyId);

const outputRoot = String(cfg.output_root || '/home/node/.n8n/odoo_forensic_exports').replace(/\/$/, '');
const snapRoot = path.join(outputRoot, snapshotId);

fs.mkdirSync(snapRoot, { recursive: true });

const runContext = {
  snapshot_id: snapshotId,
  date_start: dateStart,
  date_end: dateEnd,
  period_label: cfg.period_label ? String(cfg.period_label).trim() : null,
  company_id: targetCompanyId,
  company_name: cfg.target_company_name || 'Ride Electric Brisbane',
  timezone: cfg.timezone || 'Australia/Brisbane',
  created_at: now,
};

fs.writeFileSync(
  path.join(snapRoot, 'snapshot_run_context.json'),
  JSON.stringify(runContext, null, 2),
  'utf8',
);

return [{
  json: {
    snapshot_id: snapshotId,
    timezone: cfg.timezone || 'Australia/Brisbane',

    odoo_base_url: String(required('odoo_base_url')).replace(/\/$/, ''),
    odoo_db: required('odoo_db'),
    odoo_username: required('odoo_username'),
    odoo_api_key_or_password: required('odoo_api_key_or_password'),

    target_company_id: targetCompanyId,
    target_company_name: cfg.target_company_name || 'Ride Electric Brisbane',
    company_context_ids: companyContextIds,

    date_start: dateStart,
    date_end: dateEnd,
    period_label: runContext.period_label,

    output_root: outputRoot,
    page_limit: Number(cfg.page_limit || 500),

    subworkflow_01_account_ledger_id: required('subworkflow_01_account_ledger_id'),
    subworkflow_02_pos_retail_id: cfg.subworkflow_02_pos_retail_id || required('subworkflow_02_pos_retail_id'),

    subworkflow_03_sanitise_profile_id: cfg.subworkflow_03_sanitise_profile_id || required('subworkflow_03_sanitise_profile_id'),
    subworkflow_04_claude_audit_id: cfg.subworkflow_04_claude_audit_id || required('subworkflow_04_claude_audit_id'),
    claude_model: cfg.claude_model || 'claude-sonnet-4-20250514',

    max_anomaly_evidence_rows: Number(cfg.max_anomaly_evidence_rows || 500),
    max_claude_evidence_rows: Number(cfg.max_claude_evidence_rows || 50),

    snapshot_run_context_path: path.join(snapRoot, 'snapshot_run_context.json'),
    period_preview: cfg.period_preview || null,
  },
}];

const ledger = $('Run 01 Sub - Account Ledger').first().json;
const pos = $('Run 02 Sub - POS Retail').first().json;
const sanitise = $('Run 03 Sub - Sanitise Profile').first().json;
const masterData = $('Run 05 Sub - Master Data').first().json;
const githubPush = $('Run 04 Sub - Claude Audit').first().json;
const rawPush = $input.first().json;

const snapshotId =
  rawPush.snapshot_id ||
  githubPush.snapshot_id ||
  masterData.snapshot_id ||
  sanitise.snapshot_id ||
  pos.snapshot_id ||
  ledger.snapshot_id;

return [{
  json: {
    snapshot_id: snapshotId,
    stage_01_account_ledger: ledger,
    stage_02_pos_retail: pos,
    stage_03_sanitise_profile: sanitise,
    stage_05_master_data: masterData,
    stage_04_github_push: githubPush,
    stage_06_raw_github_push: rawPush,
    core_completed_at: new Date().toISOString(),
    readiness_status: sanitise.readiness_status || null,
    github_audit_package_url: githubPush.audit_exports_url || null,
    opus_entry_point: githubPush.opus_entry_point || null,
    github_raw_data_url: rawPush.raw_data_url || null,
    raw_files_pushed: rawPush.files_pushed || null,
  },
}];

const ctx = $('Build Snapshot Context').first().json;
const ledger = $('Run 01 Sub - Account Ledger').first().json;
return [{
  json: {
    ...ctx,
    snapshot_id: ledger.snapshot_id || ctx.snapshot_id,
    stage_01_ledger_summary: ledger.summary || null,
  },
}];

const ctx = $('Build Snapshot Context').first().json;
const ledger = $('Run 01 Sub - Account Ledger').first().json;
const pos = $('Run 02 Sub - POS Retail').first().json;

return [{
  json: {
    ...ctx,
    snapshot_id: pos.snapshot_id || ledger.snapshot_id || ctx.snapshot_id,
    stage_01_summary: ledger,
    stage_02_summary: pos,
  },
}];

const ctx = $('Build Snapshot Context').first().json;
const sanitise = $('Run 03 Sub - Sanitise Profile').first().json;

return [{
  json: {
    snapshot_id: sanitise.snapshot_id || ctx.snapshot_id,
    output_root: ctx.output_root,
    claude_model: ctx.claude_model || 'claude-sonnet-4-20250514',
    max_sample_per_model: Number(ctx.max_claude_evidence_rows || 40),
    readiness_status: sanitise.readiness_status || null,
  },
}];

const ctx = $('Build Snapshot Context').first().json;
const sanitise = $('Run 03 Sub - Sanitise Profile').first().json;

return [{
  json: {
    ...ctx,
    snapshot_id: sanitise.snapshot_id || ctx.snapshot_id,
    stage_01_summary: $('Run 01 Sub - Account Ledger').first().json || null,
    stage_02_summary: $('Run 02 Sub - POS Retail').first().json || null,
    stage_03_summary: sanitise || null,
  },
}];

// Map Form Trigger output -> complete pipeline config (form values + static config)
const staticCfg = {"odoo_base_url": "https://rid002-17-dev.black.wedoo.co.nz", "odoo_db": "RE-Staging-2026-01-08", "odoo_username": "research@rideelectric.com.au", "odoo_api_key_or_password": " Sky33line!!", "output_root": "/home/node/.n8n/odoo_forensic_exports", "page_limit": 1000, "subworkflow_01_account_ledger_id": "1HXbApqBqDVNVbCa", "max_anomaly_evidence_rows": 500, "max_claude_evidence_rows": 50, "subworkflow_02_pos_retail_id": "ZPOS02Brisbane01", "subworkflow_03_sanitise_profile_id": "ZSAN03Brisbane01", "subworkflow_04_claude_audit_id": "ZCLA04Brisbane01", "claude_model": "claude-sonnet-4-20250514"};
const companyMap = {"Ride Electric Brisbane": {"id": 4, "timezone": "Australia/Brisbane"}, "Ride Electric Gold Coast": {"id": 5, "timezone": "Australia/Brisbane"}, "Ride Electric Adelaide": {"id": 6, "timezone": "Australia/Adelaide"}, "Ride Electric Sydney": {"id": 7, "timezone": "Australia/Sydney"}};
const fyMap = {"FY 2024-25 (1 Jul 2024 \u2013 30 Jun 2025)": {"start": "2024-07-01", "end": "2025-06-30"}, "FY 2023-24 (1 Jul 2023 \u2013 30 Jun 2024)": {"start": "2023-07-01", "end": "2024-06-30"}, "FY 2022-23 (1 Jul 2022 \u2013 30 Jun 2023)": {"start": "2022-07-01", "end": "2023-06-30"}, "Custom \u2014 use Date From / Date To below": {"start": "", "end": ""}};

const input = $input.first().json;

const companyLabel = String(input['Business'] || '').trim();
const fyLabel      = String(input['Financial Year'] || '').trim();
const customStart  = String(input['Date From'] || '').trim();
const customEnd    = String(input['Date To']   || '').trim();

if (!companyMap[companyLabel]) {
  throw new Error('Unknown business: ' + companyLabel + '. Options: ' + Object.keys(companyMap).join(', '));
}
const company = companyMap[companyLabel];

let dateStart, dateEnd;
if (fyLabel.startsWith('Custom')) {
  dateStart = customStart;
  dateEnd   = customEnd;
  if (!dateStart || !dateEnd) throw new Error('Custom period selected but Date From / Date To are empty.');
} else {
  const fy = fyMap[fyLabel];
  if (!fy) throw new Error('Unknown FY preset: ' + fyLabel);
  dateStart = fy.start;
  dateEnd   = fy.end;
}

const isoRe = /^\d{4}-\d{2}-\d{2}$/;
if (!isoRe.test(dateStart) || !isoRe.test(dateEnd)) throw new Error('Dates must be YYYY-MM-DD. Got: ' + dateStart + ' / ' + dateEnd);
if (dateStart >= dateEnd) throw new Error('Date From must be before Date To.');

return [{ json: {
  ...staticCfg,
  target_company_id:   company.id,
  target_company_name: companyLabel,
  company_context_ids: company.id,
  timezone:            company.timezone,
  date_start:          dateStart,
  date_end:            dateEnd,
  period_label:        fyLabel.startsWith('Custom') ? dateStart + ' to ' + dateEnd : fyLabel,
  snapshot_id:         '',
} }];

// Parse Qwen JSON output and produce complete pipeline config
const staticCfg = {"odoo_base_url": "https://rid002-17-dev.black.wedoo.co.nz", "odoo_db": "RE-Staging-2026-01-08", "odoo_username": "research@rideelectric.com.au", "odoo_api_key_or_password": " Sky33line!!", "output_root": "/home/node/.n8n/odoo_forensic_exports", "page_limit": 1000, "subworkflow_01_account_ledger_id": "1HXbApqBqDVNVbCa", "max_anomaly_evidence_rows": 500, "max_claude_evidence_rows": 50, "subworkflow_02_pos_retail_id": "ZPOS02Brisbane01", "subworkflow_03_sanitise_profile_id": "ZSAN03Brisbane01", "subworkflow_04_claude_audit_id": "ZCLA04Brisbane01", "claude_model": "claude-sonnet-4-20250514"};
const companyMap = {"Ride Electric Brisbane": {"id": 4, "timezone": "Australia/Brisbane"}, "Ride Electric Gold Coast": {"id": 5, "timezone": "Australia/Brisbane"}, "Ride Electric Adelaide": {"id": 6, "timezone": "Australia/Adelaide"}, "Ride Electric Sydney": {"id": 7, "timezone": "Australia/Sydney"}};
const raw = $input.first().json;

let parsed;
try {
  const text = (raw.text || raw.message || raw.response || JSON.stringify(raw)).replace(/```json|```/g, '').trim();
  parsed = JSON.parse(text);
} catch (e) {
  throw new Error('Qwen did not return valid JSON: ' + e.message);
}

const companyLabel = String(parsed.company_name || 'Ride Electric Brisbane').trim();
const dateStart    = String(parsed.date_start || '').trim();
const dateEnd      = String(parsed.date_end   || '').trim();

if (!companyMap[companyLabel]) throw new Error('Unknown company from Qwen: ' + companyLabel);
const company = companyMap[companyLabel];

return [{ json: {
  ...staticCfg,
  target_company_id:   company.id,
  target_company_name: companyLabel,
  company_context_ids: company.id,
  timezone:            company.timezone,
  date_start:          dateStart,
  date_end:            dateEnd,
  period_label:        dateStart + ' to ' + dateEnd,
  snapshot_id:         '',
} }];

// Paste into orchestrator Code node: "Validate And Preview Period"
// Runs after Select Audit Period — validates dates and outputs a human-readable preview.
// Fail closed before the Wait gate if dates are invalid.

const cfg = { ...$input.first().json };

function required(name) {
  if (
    cfg[name] === undefined ||
    cfg[name] === null ||
    String(cfg[name]).trim() === '' ||
    String(cfg[name]).startsWith('PUT_') ||
    String(cfg[name]).startsWith('PASTE_')
  ) {
    throw new Error(`Missing required period field: ${name}`);
  }
  return String(cfg[name]).trim();
}

function isIsoDate(s) {
  return /^\d{4}-\d{2}-\d{2}$/.test(s) && !Number.isNaN(Date.parse(s));
}

const dateStart = required('date_start');
const dateEnd = required('date_end');

if (!isIsoDate(dateStart)) throw new Error(`date_start must be YYYY-MM-DD, got: ${dateStart}`);
if (!isIsoDate(dateEnd)) throw new Error(`date_end must be YYYY-MM-DD, got: ${dateEnd}`);
if (dateStart >= dateEnd) throw new Error(`date_start (${dateStart}) must be before date_end (${dateEnd})`);

const periodLabel = cfg.period_label ? String(cfg.period_label).trim() : '';
const snapshotOverride = cfg.snapshot_id ? String(cfg.snapshot_id).trim() : '';
const fyEndYear = dateEnd.slice(0, 4);
const now = new Date().toISOString();
const plannedSnapshotId = snapshotOverride || `eofy_${fyEndYear}_brisbane_${now.replace(/[:.]/g, '-')}`;

return [{
  json: {
    ...cfg,
    date_start: dateStart,
    date_end: dateEnd,
    period_label: periodLabel,
    snapshot_id: snapshotOverride,
    period_preview: {
      date_start: dateStart,
      date_end: dateEnd,
      period_label: periodLabel || null,
      fy_end_year: fyEndYear,
      planned_snapshot_id: plannedSnapshotId,
      company_id: cfg.target_company_id,
      company_name: cfg.target_company_name || 'Ride Electric Brisbane',
      message: 'Review period_preview, then Resume this execution to start Odoo extraction.',
      resume_hint: 'Click Resume in the n8n execution panel, or call $execution.resumeUrl',
    },
  },
}];

const ctx = $('Build Snapshot Context').first().json;
const githubPush = $('Run 04 Sub - Claude Audit').first().json;
return [{ json: {
  snapshot_id: githubPush.snapshot_id || ctx.snapshot_id,
  output_root: ctx.output_root || '/home/node/.n8n/odoo_forensic_exports',
} }];
